1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSlideIndicator } from '../zimmSlideIndicator';
5	import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
6	import { CARD_SLOT } from '../../zimmProductCardShared';
7	
8	/**
9	 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
10	 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
11	 * these descendants for hover-reveal styling without reaching into implementation details.
12	 * Do not rename these values without updating that recipe too:
13	 *   - "media"     — the outermost element (this component's root)
14	 *   - "badge"     — the merchandiser badge label, top-left of the image (present only when a
15	 *                   non-empty `badge` is supplied)
16	 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
17	 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
18	 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
19	 */
20	
21	const messages = defineMessages({
22	  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
23	  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
24	  /**
25	   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
26	   * distinct from the hover-capable-only `carousel` arrows and the touch-only
27	   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
28	   * pointer capability. See `canNavigateByKeyboard` below.
29	   */
30	  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
31	});
32	
33	const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';
34	
35	/** One image the card can show — always a real, non-empty product-photo description. */
36	export type ZimmProductCardMediaImage = {
37	  src: string;
38	  alt: string;
39	};
40	
41	export type ZimmProductCardMediaProps = {
42	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
43	  primaryImage: ZimmProductCardMediaImage;
44	  /**
45	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
46	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
47	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
48	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
49	   * content. Has no effect unless `swapOnHover` is also true.
50	   */
51	  hoverImage?: ZimmProductCardMediaImage;
52	  /**
53	   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
54	   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
55	   * `hoverImage`'s note above for why the two features don't combine).
56	   */
57	  images?: ZimmProductCardMediaImage[];
58	  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
59	  swapOnHover: boolean;
60	  /**
61	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
62	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
63	   * — it renders whenever there is more than one image to page through, regardless of this prop.
64	   */
65	  showControls: boolean;
66	  /**
67	   * Merchandiser-configured badge label (e.g. "Runway", "Exclusive") — SFCC-236's Figma "Tag"
68	   * overlay, top-left of the image. Renders only when non-empty; a blank/whitespace-only value
69	   * behaves identically to omitting the prop, same guard shape as `removeLabel` below. Which
70	   * variations actually show a badge (PLP/Wishlist yes, Home no) is the organism's job via its
71	   * `VARIATION_CONFIG` — this component only renders what it's given.
72	   */
73	  badge?: string;
74	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
75	  onRemove?: () => void;
76	  /**
77	   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
78	   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
79	   * independent optional props rather than a discriminated union because this is a simple
80	   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
81	   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
82	   * all rather than shipping an unlabelled, inaccessible button — see the component body.
83	   */
84	  removeLabel?: string;
85	  /**
86	   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
87	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
88	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
89	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
90	   */
91	  priority?: boolean;
92	};
93	
94	/**
95	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
96	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
97	 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
98	 *
99	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
100	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
101	 * the slide indicator are mutually exclusive by pointer capability
102	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
103	 * exist in the DOM at all times, gated via CSS rather than a JS `window.matchMedia` check —
104	 * matching the "keep in DOM, hide via CSS" precedent `ZimmColourSwatchGroup` already uses for its
105	 * off-page swatches — so server and client render identically (no hydration mismatch) and
106	 * neither affordance depends on `matchMedia`, which jsdom (this component's own Vitest
107	 * environment) does not implement. The two affordances differ in *where* that CSS lives, though:
108	 * the indicator is fully gated by this recipe's own media query. The arrows are not — this
109	 * recipe only ever sets them to `display: none`; the actual reveal (`display: flex`, on
110	 * `&:hover`/`&:has(:focus-visible)`) lives in the composing `ZimmProductCard` organism's own recipe,
111	 * since the AC and Figma both specify arrows appear on an actual hover/focus interaction with the
112	 * whole card, not merely "device supports hover" — the same interaction-gated pattern already
113	 * used there for price/size-chips/notify-me. A story rendering this component standalone (see
114	 * this file's own `index.stories.tsx`) therefore never shows the arrows, by design.
115	 *
116	 * A third, always-available operability layer sits underneath both visual affordances: the
117	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
118	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
119	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
120	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
121	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
122	 */
123	export const ZimmProductCardMedia = ({
124	  primaryImage,
125	  hoverImage,
126	  images,
127	  swapOnHover,
128	  showControls,
129	  badge,
130	  onRemove,
131	  removeLabel,
132	  priority,
133	}: ZimmProductCardMediaProps) => {
134	  const intl = useIntl();
135	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
136	
137	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
138	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
139	  const gallery = images && images.length > 1 ? images : undefined;
140	  const slideImages = gallery ?? [primaryImage];
141	  const totalSlides = slideImages.length;
142	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
143	  const canPage = totalSlides > 1 && showControls;
144	  // Keyboard operability is independent of `showControls` — deliberately not folded into
145	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
146	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
147	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
148	  // so this is the only paging affordance such a user has, regardless of `showControls`.
149	  const canNavigateByKeyboard = totalSlides > 1;
150	
151	  // Single piece of state, per this codebase's extract-to-hook threshold
152	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
153	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
154	  // because this build step's file manifest is limited to this component's own 4 files; a hook
155	  // would be a 5th file outside that scope.
156	  const [currentIndex, setCurrentIndex] = useState(0);
157	  const scrollContainerRef = useRef<HTMLDivElement>(null);
158	
159	  const scrollToIndex = (index: number) => {
160	    const container = scrollContainerRef.current;
161	    if (!container || typeof container.scrollTo !== 'function') return;
162	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
163	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
164	    // browser reports a real width so the requested slide scrolls fully into view.
165	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
166	  };
167	
168	  const goToRelativeSlide = (delta: 1 | -1) => {
169	    if (totalSlides <= 1) return;
170	    const next = (currentIndex + delta + totalSlides) % totalSlides;
171	    setCurrentIndex(next);
172	    scrollToIndex(next);
173	  };
174	
175	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
176	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
177	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
178	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
179	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
180	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
181	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
182	  useEffect(() => {
183	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
184	  }, [totalSlides]);
185	
186	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
187	  // capability — additive to, and independent of, the hover-capable-only arrows and the
188	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
189	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
190	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
191	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
192	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
193	    event.preventDefault();
194	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
195	  };
196	
197	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
198	  // calls goToRelativeSlide at all. `scrollend` (Baseline 2024 — Chrome 114+, Firefox 109+,
199	  // Safari 18+) fires once the snap gesture settles. No `scroll`-event fallback for older
200	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
201	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
202	  // interaction.
203	  useEffect(() => {
204	    const container = scrollContainerRef.current;
205	    if (!container || totalSlides <= 1) return undefined;
206	
207	    const handleScrollEnd = () => {
208	      const slideWidth = container.clientWidth || 1;
209	      const nearest = Math.round(container.scrollLeft / slideWidth);
210	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
211	    };
212	
213	    container.addEventListener('scrollend', handleScrollEnd);
214	    return () => container.removeEventListener('scrollend', handleScrollEnd);
215	  }, [totalSlides]);
216	
217	  // Non-primary images are always lazy; only the first slide's own base image can opt into
218	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
219	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
220	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
221	
222	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
223	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
224	  const hasBadge = typeof badge === 'string' && badge.trim().length > 0;
225	
226	  return (
227	    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.media}>
228	      <chakra.div
229	        ref={scrollContainerRef}
230	        __css={styles.scrollContainer}
231	        data-testid="card-media-scroll"
232	        role={canNavigateByKeyboard ? 'group' : undefined}
233	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
234	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
235	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
236	      >
237	        {slideImages.map((image, index) => {
238	          const isPrimaryPosition = index === 0;
239	
240	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
241	            return (
242	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
243	                <chakra.img
244	                  src={image.src}
245	                  alt={image.alt}
246	                  data-role="hover-base"
247	                  __css={styles.hoverSwapBase}
248	                  {...imageLoadingProps(true)}
249	                />
250	                <chakra.img
251	                  src={hoverImage.src}
252	                  alt={hoverImage.alt}
253	                  data-role="hover-overlay"
254	                  __css={styles.hoverSwapOverlay}
255	                  {...imageLoadingProps(false)}
256	                />
257	              </chakra.div>
258	            );
259	          }
260	
261	          return (
262	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
263	              <chakra.img
264	                src={image.src}
265	                alt={image.alt}
266	                __css={styles.image}
267	                {...imageLoadingProps(isPrimaryPosition)}
268	              />
269	            </chakra.div>
270	          );
271	        })}
272	      </chakra.div>
273	
274	      {hasBadge && (
275	        <chakra.div __css={styles.badge} data-card-slot={CARD_SLOT.badge}>
276	          <chakra.span __css={styles.badgeLabel}>{badge}</chakra.span>
277	        </chakra.div>
278	      )}
279	
280	      {showRemove && (
281	        <chakra.button
282	          type="button"
283	          __css={styles.close}
284	          data-card-slot={CARD_SLOT.close}
285	          aria-label={removeLabel}
286	          onClick={onRemove}
287	        >
288	          <CloseIcon aria-hidden boxSize="var(--zimm-icon-size-md)" />
289	        </chakra.button>
290	      )}
291	
292	      {canPage && (
293	        <chakra.div __css={styles.carousel} data-card-slot={CARD_SLOT.carousel}>
294	          <chakra.button
295	            type="button"
296	            __css={styles.arrowButton}
297	            aria-label={intl.formatMessage(messages.previousImage)}
298	            onClick={() => goToRelativeSlide(-1)}
299	          >
300	            <ChevronLeftIcon aria-hidden />
301	          </chakra.button>
302	          <chakra.button
303	            type="button"
304	            __css={styles.arrowButton}
305	            aria-label={intl.formatMessage(messages.nextImage)}
306	            onClick={() => goToRelativeSlide(1)}
307	          >
308	            <ChevronRightIcon aria-hidden />
309	          </chakra.button>
310	        </chakra.div>
311	      )}
312	
313	      {totalSlides > 1 && (
314	        <chakra.div __css={styles.indicatorWrapper} data-card-slot={CARD_SLOT.indicator}>
315	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
316	        </chakra.div>
317	      )}
318	    </chakra.div>
319	  );
320	};
321	
322	export default ZimmProductCardMedia;
